<?php
namespace App\Console\Commands;
use App\Models\CmsPreviewToken;use Illuminate\Console\Command;use Illuminate\Notifications\DatabaseNotification;use Laravel\Sanctum\PersonalAccessToken;
class PruneExpiredOperationalData extends Command{protected $signature='practice:prune-expired {--execute : Permanently remove the identified expired records}';protected $description='Report or remove explicitly supported expired operational records';public function handle():int{$queries=['expired preview tokens'=>CmsPreviewToken::where('expires_at','<',now()),'expired mobile tokens'=>PersonalAccessToken::where('expires_at','<',now()),'old read notifications'=>DatabaseNotification::whereNotNull('read_at')->where('created_at','<',now()->subYear())];foreach($queries as $label=>$query){$count=(clone$query)->count();$this->line("{$label}: {$count}");if($this->option('execute')&&$count)$query->delete();}$this->info($this->option('execute')?'Expired operational records removed.':'Dry run only. Pass --execute to remove these records.');return self::SUCCESS;}}
